import * as M from 'node:buffer';
function p(name: string, fn: () => any): void {
  try { console.log(name, String(fn())); } catch (e: any) { console.log(name, 'THROW', e.name, e.code, e.message); }
}
function main(): void {
  p('atob()', () => { const f: any = M.atob; return f(); });
  p('btoa()', () => { const f: any = M.btoa; return f(); });
  p('atob(x)', () => { const f: any = M.atob; return f('aGk='); });
  p('btoa(x)', () => { const f: any = M.btoa; return f('hi'); });
  console.log(M.atob('aGk='), M.btoa('hi'), M.atob.length, M.btoa.length);
  try { M.atob('***'); } catch (e: any) { console.log(e.name); }
}
